import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { api, LLMProvider, LLMModel } from '@/lib/api'
import { Brain, Key, CheckCircle, AlertCircle, ChevronRight, ExternalLink, Trash2 } from 'lucide-react'
import { toast } from 'sonner'

// 提供商图标映射（使用首字母作为简单标识）
const PROVIDER_ICONS: Record<string, string> = {
  ernie: '文',
  qwen: '通',
  glm: '智',
  kimi: 'K',
  baichuan: '百',
  sparkdesk: '讯',
}

const PROVIDER_COLORS: Record<string, string> = {
  ernie: 'bg-blue-500',
  qwen: 'bg-purple-500',
  glm: 'bg-indigo-500',
  kimi: 'bg-cyan-500',
  baichuan: 'bg-orange-500',
  sparkdesk: 'bg-red-500',
}

export function LLM() {
  const queryClient = useQueryClient()
  const { data: providers = [] } = useQuery({ queryKey: ['llm-providers'], queryFn: api.getLLMProviders })
  const { data: config } = useQuery({ queryKey: ['llm-config'], queryFn: api.getLLMConfig })

  const [selectedProvider, setSelectedProvider] = useState<string | null>(null)
  const [apiKey, setApiKey] = useState('')
  const [apiBase, setApiBase] = useState('')
  const [submitting, setSubmitting] = useState(false)

  // 模型选择
  const [modelName, setModelName] = useState('')
  const [fastModelName, setFastModelName] = useState('')
  const [providerModels, setProviderModels] = useState<LLMModel[]>([])

  // 选择提供商
  const handleSelectProvider = async (provider: LLMProvider) => {
    setSelectedProvider(provider.name)
    setApiBase(provider.default_api_base)
    setApiKey('')
    try {
      const models = await api.getLLMProviderModels(provider.name)
      setProviderModels(models)
      if (models.length > 0) {
        setModelName(models[0].id)
        setFastModelName(models.length > 1 ? models[1].id : models[0].id)
      }
    } catch (e) {
      console.error('获取模型列表失败:', e)
      setProviderModels([])
    }
  }

  // 保存凭据
  const handleSaveCredentials = async () => {
    if (!selectedProvider || !apiKey.trim()) {
      toast.error('请输入 API Key')
      return
    }
    setSubmitting(true)
    try {
      const result = await api.putLLMCredentials({
        provider: selectedProvider,
        api_key: apiKey.trim(),
        api_base: apiBase.trim() || undefined,
      })
      if (result.error) {
        toast.error(result.error)
      } else {
        toast.success('凭据已保存')
        queryClient.invalidateQueries({ queryKey: ['llm-config'] })
      }
    } catch (e) {
      toast.error((e as Error).message)
    } finally {
      setSubmitting(false)
    }
  }

  // 保存模型选择
  const handleSaveModels = async () => {
    if (!modelName) {
      toast.error('请选择主模型')
      return
    }
    setSubmitting(true)
    try {
      const result = await api.putLLMModels({
        model_name: modelName,
        fast_model_name: fastModelName || undefined,
      })
      if (result.error) {
        toast.error(result.error)
      } else {
        toast.success('模型已配置')
        queryClient.invalidateQueries({ queryKey: ['llm-config'] })
        queryClient.invalidateQueries({ queryKey: ['config'] })
      }
    } catch (e) {
      toast.error((e as Error).message)
    } finally {
      setSubmitting(false)
    }
  }

  // 清除配置
  const handleClearConfig = async () => {
    if (!confirm('确定要清除 LLM 配置吗？')) return
    try {
      await api.deleteLLMCredentials()
      toast.success('LLM 配置已清除')
      queryClient.invalidateQueries({ queryKey: ['llm-config'] })
      queryClient.invalidateQueries({ queryKey: ['config'] })
      setSelectedProvider(null)
      setApiKey('')
    } catch (e) {
      toast.error((e as Error).message)
    }
  }

  // 当前配置的提供商
  const currentProvider = providers.find(p => p.name === config?.provider)

  return (
    <div className="p-6 space-y-6">
      <div>
        <h2 className="text-2xl font-bold">模型提供商</h2>
        <p className="text-muted-foreground">配置 LLM 模型提供商和模型</p>
      </div>

      {/* 当前配置状态 */}
      {config?.configured && (
        <div className="rounded-xl border bg-green-50 p-4">
          <h3 className="font-medium mb-3 flex items-center gap-2 text-green-700">
            <CheckCircle className="h-4 w-4" /> 当前配置
          </h3>
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
            <div className="rounded-lg bg-white p-3">
              <p className="text-xs text-muted-foreground">提供商</p>
              <p className="font-medium text-sm">{config.provider_info?.display_name || config.provider}</p>
            </div>
            <div className="rounded-lg bg-white p-3">
              <p className="text-xs text-muted-foreground">API Key</p>
              <p className="font-mono text-sm">{config.api_key_masked}</p>
            </div>
            <div className="rounded-lg bg-white p-3">
              <p className="text-xs text-muted-foreground">主模型</p>
              <p className="font-mono text-sm">{config.model_name}</p>
            </div>
            <div className="rounded-lg bg-white p-3">
              <p className="text-xs text-muted-foreground">快速模型</p>
              <p className="font-mono text-sm">{config.fast_model_name}</p>
            </div>
          </div>
          <button
            onClick={handleClearConfig}
            className="mt-3 inline-flex items-center gap-1.5 rounded-lg border border-red-200 px-3 py-1.5 text-sm text-red-600 hover:bg-red-50"
          >
            <Trash2 className="h-3.5 w-3.5" />
            清除配置
          </button>
        </div>
      )}

      {/* 提供商列表 */}
      <div className="space-y-3">
        <h3 className="font-medium flex items-center gap-2">
          <Brain className="h-4 w-4 text-primary" /> 选择模型提供商
        </h3>
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {providers.map(provider => (
            <div
              key={provider.name}
              onClick={() => handleSelectProvider(provider)}
              className={`rounded-xl border p-4 cursor-pointer transition-all hover:shadow-md ${
                selectedProvider === provider.name
                  ? 'border-primary bg-primary/5'
                  : 'bg-card hover:border-primary/50'
              }`}
            >
              <div className="flex items-start gap-3">
                <div className={`flex h-10 w-10 items-center justify-center rounded-lg text-white font-bold ${PROVIDER_COLORS[provider.name] || 'bg-gray-500'}`}>
                  {PROVIDER_ICONS[provider.name] || provider.name[0].toUpperCase()}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <p className="font-medium truncate">{provider.display_name}</p>
                    {currentProvider?.name === provider.name && (
                      <CheckCircle className="h-4 w-4 text-green-500 flex-shrink-0" />
                    )}
                  </div>
                  <p className="text-xs text-muted-foreground line-clamp-2 mt-1">
                    {provider.description}
                  </p>
                  <p className="text-xs text-muted-foreground mt-2">
                    {provider.model_count} 个模型
                  </p>
                </div>
                <ChevronRight className="h-4 w-4 text-muted-foreground flex-shrink-0" />
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* 配置面板 */}
      {selectedProvider && (
        <div className="rounded-xl border bg-card p-4 space-y-4">
          <h3 className="font-medium flex items-center gap-2">
            <Key className="h-4 w-4 text-primary" /> 配置 {providers.find(p => p.name === selectedProvider)?.display_name}
          </h3>

          {/* API Key */}
          <div className="space-y-2">
            <label className="text-sm font-medium">API Key</label>
            <input
              type="password"
              value={apiKey}
              onChange={e => setApiKey(e.target.value)}
              placeholder="输入 API Key"
              className="w-full rounded-lg border bg-background px-3 py-2 text-sm font-mono placeholder:text-muted-foreground/50 focus:outline-none focus:ring-2 focus:ring-primary/30"
            />
          </div>

          {/* API Base */}
          <div className="space-y-2">
            <label className="text-sm font-medium">API Base URL</label>
            <input
              type="text"
              value={apiBase}
              onChange={e => setApiBase(e.target.value)}
              placeholder="API Base URL"
              className="w-full rounded-lg border bg-background px-3 py-2 text-sm font-mono placeholder:text-muted-foreground/50 focus:outline-none focus:ring-2 focus:ring-primary/30"
            />
            <p className="text-xs text-muted-foreground">
              默认: {providers.find(p => p.name === selectedProvider)?.default_api_base}
            </p>
          </div>

          {/* 保存凭据按钮 */}
          <button
            onClick={handleSaveCredentials}
            disabled={submitting || !apiKey.trim()}
            className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground hover:bg-primary/90 disabled:opacity-50"
          >
            {submitting ? '保存中...' : '保存凭据'}
          </button>

          {/* 模型选择 */}
          {providerModels.length > 0 && (
            <div className="pt-4 border-t space-y-4">
              <h4 className="text-sm font-medium">选择模型</h4>
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <label className="text-sm font-medium">主模型</label>
                  <select
                    value={modelName}
                    onChange={e => setModelName(e.target.value)}
                    className="w-full rounded-lg border bg-background px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/30"
                  >
                    {providerModels.map(m => (
                      <option key={m.id} value={m.id}>
                        {m.name} ({(m.context_length / 1024).toFixed(0)}K)
                      </option>
                    ))}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-medium">快速模型</label>
                  <select
                    value={fastModelName}
                    onChange={e => setFastModelName(e.target.value)}
                    className="w-full rounded-lg border bg-background px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/30"
                  >
                    {providerModels.map(m => (
                      <option key={m.id} value={m.id}>
                        {m.name} ({(m.context_length / 1024).toFixed(0)}K)
                      </option>
                    ))}
                  </select>
                </div>
              </div>
              <button
                onClick={handleSaveModels}
                disabled={submitting || !modelName}
                className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground hover:bg-primary/90 disabled:opacity-50"
              >
                {submitting ? '保存中...' : '保存模型选择'}
              </button>
            </div>
          )}

          {/* 帮助链接 */}
          {providers.find(p => p.name === selectedProvider)?.help_url && (
            <div className="pt-4 border-t">
              <a
                href={providers.find(p => p.name === selectedProvider)?.help_url}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-1 text-sm text-primary hover:underline"
              >
                <ExternalLink className="h-3.5 w-3.5" />
                查看 API Key 获取指南
              </a>
            </div>
          )}
        </div>
      )}

      {/* 未配置提示 */}
      {!config?.configured && !selectedProvider && (
        <div className="rounded-xl border border-dashed bg-muted/30 p-6 text-center">
          <AlertCircle className="h-8 w-8 text-muted-foreground mx-auto mb-2" />
          <p className="text-muted-foreground">请选择一个模型提供商开始配置</p>
        </div>
      )}
    </div>
  )
}
